alter table public.products
  alter column description drop not null,
  alter column price drop not null,
  alter column stock_quantity drop not null,
  add column if not exists needs_pricing boolean not null default false;

insert into public.categories (name, slug, description, is_active)
values ('Beauty & Personal Care', 'beauty-personal-care', 'Beauty and personal care products.', true)
on conflict (slug) do update set name = excluded.name, description = excluded.description, is_active = true;

update public.products
set is_active = false
where slug in ('premium-jasmine-rice', 'fresh-plantains', 'red-palm-oil', 'cassava-flour', 'suya-spice-blend', 'hibiscus-drink', 'plantain-chips');

